def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def = 0
    my_def = 0
    for i in range(n):
        if my[i] == 'D':
            my_def += 1
        if op[i] == 'D':
            opp_def += 1

    last_my = my[-1]
    last_opp = op[-1]

    if opp_def == 0:
        if my_def == 0:
            if n >= 20:
                return 'D'
            return 'C'

        if my_def == 1:
            if last_my == 'D' and last_opp == 'C':
                return 'C'
            if last_my == 'C' and last_opp == 'C':
                return 'D'
            return 'D' if n >= 21 else 'C'

        return 'D'

    d5 = 0
    start5 = n - 5 if n >= 5 else 0
    for i in range(start5, n):
        if op[i] == 'D':
            d5 += 1

    d10 = 0
    start10 = n - 10 if n >= 10 else 0
    for i in range(start10, n):
        if op[i] == 'D':
            d10 += 1

    if opp_def * 2 > n or d5 >= 4 or d10 >= 7:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if d5 >= 3 or opp_def * 3 > n:
                return 'D'
            return 'C'

        if n >= 2 and my[-2] == 'D':
            if d5 >= 3 or opp_def * 3 > n:
                return 'D'
            return 'C'

        return 'D'

    return 'C'
